import { useMemo, useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router-dom";
import { getRunDetail, getRunIdeas } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { PIPELINE_STAGES } from "@/lib/constants";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  CheckCircle2,
  Circle,
  Loader2,
  AlertTriangle,
  Play,
  Lightbulb,
  Clock,
} from "lucide-react";
import type { PipelineRunDetail, IdeaSummary } from "@/api/types";

const statusColors: Record<string, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  running: "bg-blue-100 text-blue-800",
  completed: "bg-green-100 text-green-800",
  failed: "bg-red-100 text-red-800",
};

export default function RunDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const runId = Number(id);
  const [now, setNow] = useState(Date.now());

  const {
    data: run,
    isLoading: runLoading,
    error: runError,
  } = useQuery({
    queryKey: ["run", runId],
    queryFn: () => getRunDetail(runId),
    enabled: !isNaN(runId),
  });

  const { data: ideasData } = useQuery({
    queryKey: ["run", runId, "ideas"],
    queryFn: () => getRunIdeas(runId),
    enabled: !isNaN(runId) && !!run,
  });

  // Stale run detector (BATCH-55): re-check every 30 seconds
  const isStale = useMemo(() => {
    if (!run || run.status !== "running") return false;
    const created = new Date(run.created_at).getTime();
    return Date.now() - created > 5 * 60 * 1000; // 5 minutes
  }, [run, now]);

  useEffect(() => {
    if (!run || run.status !== "running") return;
    const interval = setInterval(() => {
      setNow(Date.now());
    }, 30000);
    return () => clearInterval(interval);
  }, [run]);

  if (runError) {
    return (
      <div className="space-y-6">
        <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Dashboard
        </Button>
        <Card>
          <CardContent className="p-8 text-center" data-testid="run-not-found">
            <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-destructive" />
            <p className="text-lg font-medium">Run not found</p>
            <p className="text-sm text-muted-foreground mt-1">
              No pipeline run found with ID {id}.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (runLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!run) {
    return (
      <div className="space-y-6">
        <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Dashboard
        </Button>
        <Card>
          <CardContent className="p-8 text-center" data-testid="run-not-found">
            <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-destructive" />
            <p className="text-lg font-medium">Run not found</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const ideas = ideasData?.ideas ?? [];

  return (
    <div className="space-y-6" data-testid="run-detail">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </Button>
          <div>
            <h1 className="text-2xl font-bold tracking-tight" data-testid="run-title">
              Run #{run.id}
            </h1>
            <p className="text-sm text-muted-foreground">{run.domain}</p>
          </div>
        </div>
        <Badge className={cn("text-sm", statusColors[run.status])} data-testid="run-status">
          {run.status}
        </Badge>
      </div>

      {/* Stale Run Warning (BATCH-55) */}
      {isStale && (
        <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-4 mb-4" data-testid="stale-run-warning">
          <div className="flex items-center gap-2 text-yellow-800 dark:text-yellow-200">
            <AlertTriangle className="h-5 w-5" />
            <p className="text-sm">
              This run has been running for over 5 minutes. It may have encountered an issue.
              You can try refreshing or starting a new run.
            </p>
          </div>
        </div>
      )}

      {/* Metadata */}
      <Card data-testid="run-metadata">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Run Metadata</CardTitle>
        </CardHeader>
        <CardContent>
          <dl className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div>
              <dt className="text-muted-foreground">ID</dt>
              <dd className="font-medium">{run.id}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Domain</dt>
              <dd className="font-medium">{run.domain}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Created</dt>
              <dd className="font-medium" data-testid="run-created-at">
                {new Date(run.created_at).toLocaleString()}
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Completed</dt>
              <dd className="font-medium" data-testid="run-completed-at">
                {run.completed_at
                  ? new Date(run.completed_at).toLocaleString()
                  : "—"}
              </dd>
            </div>
          </dl>
        </CardContent>
      </Card>

      {/* Stages Timeline */}
      <Card data-testid="stages-timeline">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Stages</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {PIPELINE_STAGES.map((stage) => {
              const isCompleted = run.stages_completed.includes(stage.key);
              const isCurrent = run.current_stage === stage.key;
              return (
                <div key={stage.key} className="flex items-center gap-3">
                  {isCompleted ? (
                    <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                  ) : isCurrent ? (
                    <Loader2 className="h-5 w-5 text-blue-600 animate-spin flex-shrink-0" />
                  ) : (
                    <Circle className="h-5 w-5 text-muted-foreground flex-shrink-0" />
                  )}
                  <span
                    className={cn(
                      "text-sm",
                      isCompleted ? "text-foreground font-medium" : "text-muted-foreground",
                    )}
                  >
                    {stage.label}
                  </span>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Error Message (for failed runs) */}
      {run.status === "failed" && run.error_message && (
        <Card className="border-destructive" data-testid="error-message">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <AlertTriangle className="h-5 w-5 text-destructive flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-sm font-medium text-destructive">Pipeline Failed</p>
                <p className="text-sm text-muted-foreground mt-1">{run.error_message}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Resume Button (for failed runs) */}
      {run.status === "failed" && (
        <Button data-testid="resume-btn" className="w-full sm:w-auto">
          <Play className="h-4 w-4 mr-2" />
          Resume Pipeline
        </Button>
      )}

      {/* Generated Ideas */}
      <Card data-testid="ideas-list">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium">Generated Ideas</CardTitle>
            {ideas.length > 0 && (
              <span className="text-sm text-muted-foreground flex items-center gap-1">
                <Lightbulb className="h-4 w-4" />
                {ideas.length} idea{ideas.length !== 1 ? "s" : ""}
              </span>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {ideas.length === 0 ? (
            <p className="text-sm text-muted-foreground">No ideas generated in this run.</p>
          ) : (
            <div className="space-y-3">
              {ideas.map((idea: IdeaSummary) => (
                <Card
                  key={idea.id}
                  className="cursor-pointer hover:bg-accent/50 transition-colors"
                  onClick={() => navigate(`/ideas/${idea.id}`)}
                >
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div className="min-w-0 flex-1">
                        <p className="text-sm font-medium line-clamp-1">{idea.title}</p>
                        <p className="text-xs text-muted-foreground">{idea.domain}</p>
                      </div>
                      {idea.overall_score !== null && (
                        <Badge variant="secondary" className="ml-2">
                          {(idea.overall_score * 100).toFixed(0)}%
                        </Badge>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Duration info */}
      {run.completed_at && run.created_at && (
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Clock className="h-4 w-4" />
              <span>
                Duration:{" "}
                {(
                  (new Date(run.completed_at).getTime() -
                    new Date(run.created_at).getTime()) /
                  1000
                ).toFixed(1)}{" "}
                seconds
              </span>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

/**
 * GraphCanvas — SVG-based knowledge graph visualization (HB-01: client-side only).
 *
 * Renders entities as colored circles and relationships as lines.
 * No D3 dependency — pure SVG with React state for positioning.
 */

import { useCallback, useMemo, useRef, useState } from "react";
import type { GraphEntity, GraphRelationship } from "@/api/knowledge-graph";

// ── Color map for entity types ────────────────────────────────────

const TYPE_COLORS: Record<string, string> = {
  paper: "#3b82f6",
  author: "#10b981",
  method: "#f59e0b",
  dataset: "#8b5cf6",
  concept: "#ef4444",
};

const DEFAULT_COLOR = "#6b7280";
const NODE_RADIUS = 20;

interface LayoutNode {
  id: string;
  x: number;
  y: number;
  entity: GraphEntity;
}

// ── Simple force-directed-like layout (deterministic placement) ───

function layoutNodes(entities: GraphEntity[], width: number, height: number): LayoutNode[] {
  const cx = width / 2;
  const cy = height / 2;

  return entities.map((entity, i) => {
    const angle = (2 * Math.PI * i) / Math.max(entities.length, 1);
    const radius = Math.min(width, height) * 0.35;
    return {
      id: entity.id,
      x: cx + radius * Math.cos(angle),
      y: cy + radius * Math.sin(angle),
      entity,
    };
  });
}

interface GraphCanvasProps {
  entities: GraphEntity[];
  relationships: GraphRelationship[];
  selectedId: string | null;
  onSelectEntity: (id: string) => void;
  className?: string;
}

export function GraphCanvas({
  entities,
  relationships,
  selectedId,
  onSelectEntity,
  className,
}: GraphCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 500 });
  const [dragOffset, setDragOffset] = useState<{ x: number; y: number } | null>(null);
  const [dragNodeId, setDragNodeId] = useState<string | null>(null);

  const nodes = useMemo(
    () => layoutNodes(entities, dimensions.width, dimensions.height),
    [entities, dimensions.width, dimensions.height],
  );

  const nodeMap = useMemo(() => {
    const m = new Map<string, LayoutNode>();
    nodes.forEach((n) => m.set(n.id, n));
    return m;
  }, [nodes]);

  const handleResize = useCallback(() => {
    if (containerRef.current) {
      const { clientWidth, clientHeight } = containerRef.current;
      setDimensions({ width: clientWidth || 800, height: clientHeight || 500 });
    }
  }, []);

  // Mouse handlers for drag
  const handleMouseDown = useCallback(
    (e: React.MouseEvent, nodeId: string) => {
      e.stopPropagation();
      const node = nodeMap.get(nodeId);
      if (node) {
        setDragNodeId(nodeId);
        setDragOffset({ x: e.clientX - node.x, y: e.clientY - node.y });
      }
    },
    [nodeMap],
  );

  const handleMouseUp = useCallback(() => {
    setDragNodeId(null);
    setDragOffset(null);
  }, []);

  return (
    <div
      ref={containerRef}
      className={`relative border rounded-lg bg-background overflow-hidden ${className || ""}`}
      style={{ minHeight: 400 }}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${dimensions.width} ${dimensions.height}`}
        className="select-none"
      >
        {/* Edges */}
        {relationships.map((rel, i) => {
          const source = nodeMap.get(rel.source_id);
          const target = nodeMap.get(rel.target_id);
          if (!source || !target) return null;

          return (
            <line
              key={`edge-${i}`}
              x1={source.x}
              y1={source.y}
              x2={target.x}
              y2={target.y}
              stroke={selectedId === rel.source_id || selectedId === rel.target_id ? "#3b82f6" : "#94a3b8"}
              strokeWidth={selectedId === rel.source_id || selectedId === rel.target_id ? 2 : 1}
              opacity={0.6}
            />
          );
        })}

        {/* Nodes */}
        {nodes.map((node) => {
          const color = TYPE_COLORS[node.entity.entity_type] || DEFAULT_COLOR;
          const isSelected = node.id === selectedId;

          return (
            <g
              key={node.id}
              transform={`translate(${node.x}, ${node.y})`}
              className="cursor-pointer"
              onClick={() => onSelectEntity(node.id)}
              onMouseDown={(e) => handleMouseDown(e, node.id)}
            >
              {/* Selection ring */}
              {isSelected && (
                <circle r={NODE_RADIUS + 4} fill="none" stroke="#3b82f6" strokeWidth={2} />
              )}
              <circle
                r={NODE_RADIUS}
                fill={color}
                opacity={0.85}
                className="transition-all duration-150 hover:opacity-100"
              />
              {/* Label */}
              <text
                textAnchor="middle"
                y={NODE_RADIUS + 14}
                className="text-xs fill-muted-foreground"
                fontSize={10}
              >
                {node.entity.name.length > 18
                  ? node.entity.name.slice(0, 16) + "…"
                  : node.entity.name}
              </text>
              {/* Type badge */}
              <text
                textAnchor="middle"
                y={4}
                className="text-white text-[8px] font-bold pointer-events-none"
                fill="white"
                fontSize={8}
              >
                {node.entity.entity_type.slice(0, 3).toUpperCase()}
              </text>
            </g>
          );
        })}
      </svg>

      {/* Legend */}
      <div className="absolute bottom-2 left-2 flex gap-3 bg-background/80 backdrop-blur-sm rounded-md px-2 py-1 text-xs text-muted-foreground">
        {Object.entries(TYPE_COLORS).map(([type, color]) => (
          <span key={type} className="flex items-center gap-1">
            <span className="inline-block w-2 h-2 rounded-full" style={{ backgroundColor: color }} />
            {type}
          </span>
        ))}
      </div>
    </div>
  );
}

// --- Pipeline ---

export interface PipelineRunRequest {
  domain?: string;
  max_gaps?: number;
  generation_rounds?: number | null;
  ideas_per_round?: number | null;
  search_queries?: string[] | null;
  run_novelty?: boolean;
  run_feasibility?: boolean;
  run_synthesis?: boolean;
  export_format?: string;
  session_id?: string | null;
}

export interface PipelineRunSummary {
  id: number;
  status: "pending" | "running" | "completed" | "failed";
  domain: string;
  current_stage: string | null;
  ideas_count: number;
  session_id: string | null;
  created_at: string;
  completed_at: string | null;
  error_message: string | null;
}

export interface PipelineRunDetail extends PipelineRunSummary {
  config: Record<string, unknown>;
  stages_completed: string[];
  ideas: IdeaSummary[];
}

export interface TriggerRunResponse {
  run_id: string;
  status: string;
}

export interface AutonomousCycleRequest {
  domain?: string;
  max_runs?: number;
}

export interface AutonomousCycleResponse {
  cycle_id: string;
  status: string;
  domain: string;
  max_runs: number;
}

// --- SSE ---

export interface StageProgressEvent {
  stage: string;
  index: number;
  total: number;
  elapsed: number;
}

export interface ProgressDoneEvent {
  done: true;
}

export interface HeartbeatEvent {
  heartbeat: true;
}

export type ProgressEvent = StageProgressEvent | ProgressDoneEvent | HeartbeatEvent;

// --- Ideas ---

export interface IdeaSummary {
  id: number;
  title: string;
  domain: string;
  novelty_score: number | null;
  feasibility_score: number | null;
  overall_score: number | null;
  source_gap_ids: string[] | null;
  has_proposal: boolean;
  pipeline_run_id: number | null;
  created_at: string;
}

export interface IdeaDetail extends IdeaSummary {
  problem_statement: string;
  proposed_method: string;
  expected_contributions: string;
  source_gap_ids: string[] | null;
  novelty_report: Record<string, unknown> | null;
  feasibility_report: Record<string, unknown> | null;
  proposal_md: string | null;
  proposal_latex: string | null;
  proposal_sections: Record<string, unknown> | null;
}

export interface IdeaListResponse {
  ideas: IdeaSummary[];
  total: number;
  score_guide: Record<string, Record<string, string>>;
}

export interface IdeaFeedbackRequest {
  rating: number;
  notes?: string | null;
}

// --- Gaps ---

export interface ResearchGap {
  id: number;
  title: string;
  description: string;
  gap_type: string;
  confidence: number;
  potential_impact: string;
  idea_count: number;
  truth?: { frequency: number; confidence: number; evidence_count: number };
  related_clusters?: number[] | null;
  status?: string;
  user_rating?: number | null;
  user_notes?: string | null;
}

export interface GapListResponse {
  gaps: ResearchGap[];
  total: number;
}

// --- Knowledge ---

export interface KnowledgeSearchResult {
  id: string;
  text: string;
  metadata: Record<string, string>;
  distance: number;
}

export interface KnowledgeSearchResponse {
  query: string;
  results: KnowledgeSearchResult[];
}

export interface KnowledgeStats {
  chroma_persist_dir: string;
  embedding_provider: string;
  embedding_model: string;
  total_documents: number;
  total_chunks: number;
}

export interface IngestResponse {
  status: string;
  filename: string;
  chunks: number;
}

// --- Sessions ---

export interface SessionGroup {
  session_id: string;
  run_count: number;
  latest_run_at: string;
}

export interface SessionListResponse {
  sessions: SessionGroup[];
}

// --- Status ---

export interface SystemStatus {
  app_name: string;
  version: string;
  config: Record<string, boolean>;
  defaults: Record<string, number>;
}

// --- Global Search (BATCH-48) ---

export interface Notification {
  id: number;
  user_id: number | null;
  type: string;
  title: string;
  message: string;
  read: boolean;
  created_at: string;
}

export interface NotificationListResponse {
  notifications: Notification[];
  total: number;
}

// --- Global Search (BATCH-48) ---

export interface IdeaSearchItem {
  id: number;
  title: string;
  domain: string;
  overall_score: number;
}

export interface GapSearchItem {
  id: number;
  title: string;
  gap_type: string;
  confidence: number;
}

export interface PaperSearchItem {
  id: number;
  title: string;
  year: number;
  venue: string;
}

export interface RunSearchItem {
  id: number;
  status: string;
  domain: string;
  created_at: string;
}

export interface GlobalSearchResponse {
  query: string;
  results: {
    ideas?: { total: number; items: IdeaSearchItem[] };
    gaps?: { total: number; items: GapSearchItem[] };
